def create_dir(path):
    curr_path = None
    for p in path:
        if curr_path is None:
            curr_path = os.path.abspath(p)
        else:
            curr_path = os.path.join(curr_path, p)
        if not os.path.exists(curr_path):
            os.mkdir(curr_path)

def create_config_dir_for_first_use():
    config_dir = os.path.dirname(config_location())
    if not os.path.exists(config_dir):
        os.makedirs(config_dir)
        return True

    return False

def write_default_config(source, destination, overwrite=False):
    destination = expanduser(destination)
    if not overwrite and exists(destination):
        return

    ensure_dir_exists(destination)

    shutil.copyfile(source, destination)

def config_location():
    if platform.system() == 'Windows':
        return os.getenv('LOCALAPPDATA') + '\\dbcli\\mssqlcli\\'

    if 'XDG_CONFIG_HOME' in os.environ:
        return '%s/mssqlcli/' % expanduser(os.environ['XDG_CONFIG_HOME'])

    return expanduser('~/.config/mssqlcli/')
